package com.google.gson.internal;

import java.io.*;
import java.io.ObjectInputStream;
import java.io.ObjectStreamClass;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class UnsafeAllocator_create_TriageGen1Test {

    @Test
    public void testCreateWithSunMiscUnsafe() throws Exception {
        // Mocking sun.misc.Unsafe
        Class<?> unsafeClass = mockClass("sun.misc.Unsafe", "allocateInstance");
        Field f = unsafeClass.getDeclaredField("theUnsafe");
        f.setAccessible(true);
        final Object unsafe = f.get(null);

        Method allocateInstance = unsafeClass.getMethod("allocateInstance", Class.class);

        UnsafeAllocator allocator = UnsafeAllocator.create();
        assertNotNull("Allocator should not be null when sun.misc.Unsafe is available", allocator);

        // Test newInstance
        Class<?> testClass = mockClass("com.google.gson.internal.MockClass");
        Object instance = allocator.newInstance(testClass);

        assertTrue("newInstance should return a valid instance", instance instanceof MockClass);
    }

    @Test
    public void testCreateWithObjectStreamClass() throws Exception {
        // Mocking ObjectStreamClass
        Class<?> objectStreamClass = mockClass("java.io.ObjectStreamClass", "getConstructorId", "newInstance");

        Method getConstructorId = objectStreamClass.getDeclaredMethod("getConstructorId", Class.class);
        getConstructorId.setAccessible(true);
        final int constructorId = (Integer) getConstructorId.invoke(null, Object.class);

        Method newInstance = objectStreamClass.getDeclaredMethod("newInstance", Class.class, int.class);
        newInstance.setAccessible(true);

        UnsafeAllocator allocator = UnsafeAllocator.create();
        assertNotNull("Allocator should not be null when ObjectStreamClass is available", allocator);

        Class<?> testClass = mockClass("com.google.gson.internal.MockClass");
        Object instance = allocator.newInstance(testClass);

        assertTrue("newInstance should return a valid instance", instance instanceof MockClass);
    }

    @Test
    public void testCreateWithObjectInputStream() throws Exception {
        // Mocking ObjectInputStream
        Class<?> objectInputStreamClass = mockClass("java.io.ObjectInputStream", "newInstance");

        Method newInstance = objectInputStreamClass.getDeclaredMethod("newInstance", Class.class, Class.class);
        newInstance.setAccessible(true);

        UnsafeAllocator allocator = UnsafeAllocator.create();
        assertNotNull("Allocator should not be null when ObjectInputStream is available", allocator);

        Class<?> testClass = mockClass("com.google.gson.internal.MockClass");
        Object instance = allocator.newInstance(testClass);

        assertTrue("newInstance should return a valid instance", instance instanceof MockClass);
    }

    @Test(expected = UnsupportedOperationException.class)
    public void testCreateFallback() throws Exception {
        UnsafeAllocator allocator = UnsafeAllocator.create();
        assertNotNull("Allocator should not be null when all methods fail", allocator);

        Class<?> testClass = mockClass("com.google.gson.internal.MockClass");
        allocator.newInstance(testClass);
    }

    private Class<?> mockClass(String className, String... methods) throws Exception {
        Class<?> mockClass = mock(Class.class);
        for (String method : methods) {
            Method methodMock = mock(Method.class);
            when(mockClass.getMethod(method, Class.class)).thenReturn(methodMock);
            when(mockClass.getMethod(method, Class.class, int.class)).thenReturn(methodMock);
            when(mockClass.getMethod(method, Class.class, Class.class)).thenReturn(methodMock);
        }
        return mockClass;
    }

    @Test
    public void testUnsupportedOperationException() {
        UnsafeAllocator allocator = UnsafeAllocator.create();
        Class<?> testClass = mockClass("com.google.gson.internal.MockClass");

        try {
            allocator.newInstance(testClass);
            fail("Should have thrown UnsupportedOperationException");
        } catch (UnsupportedOperationException e) {
            assertEquals("Cannot allocate " + testClass, e.getMessage());
        }
    }
}
